import json, math, hashlib, pathlib, subprocess
from fractions import Fraction as Q
from decimal import Decimal as D, localcontext

def power(x,n):
    return x**n if n else 1

def card(t,a):
    r=(t+a)/(2*a)
    return [2*r**3-3*r**2+1,-2*r**3+3*r**2,2*a*(r**3-2*r**2+r),2*a*(r**3-r**2)]
def dcard(t,a):
    r=(t+a)/(2*a)
    return [(6*r*r-6*r)/(2*a),(-6*r*r+6*r)/(2*a),3*r*r-4*r+1,3*r*r-2*r]
def moment(c,p,m):
    return sum(math.comb(p,j)*power(c,p-j)*(-1)**j*(c**(m+j+1)-(-1)**(m+j+1))/(m+j+1) for j in range(p+1))
def kernel_moment(t,a,m):
    h=dcard(t,a)
    return moment(t,2,m)/2-h[0]*moment(-a,3,m)/6-h[1]*moment(a,3,m)/6-h[2]*moment(-a,2,m)/2-h[3]*moment(a,2,m)/2

a=Q(1,2); exact_checks=0
for t in map(Q,[-1,Q(-3,4),0,Q(1,5),1]):
    for n in range(9):
        data=[(-a)**n,a**n,n*(-a)**(n-1) if n else 0,n*a**(n-1) if n else 0]
        h=card(t,a);dh=dcard(t,a)
        if n<=3:
            assert sum(x*y for x,y in zip(h,data))==power(t,n)
            assert sum(x*y for x,y in zip(dh,data))==(n*power(t,n-1) if n else 0)
            exact_checks+=2
        if n==4:
            assert t**4-sum(x*y for x,y in zip(h,data))==(t*t-a*a)**2
            exact_checks+=1
    for m in range(9):
        n=m+4
        data=[(-a)**n,a**n,n*(-a)**(n-1),n*a**(n-1)]
        defect=n*power(t,n-1)-sum(x*y for x,y in zip(dcard(t,a),data))
        assert kernel_moment(t,a,m)==defect/math.prod(range(m+1,m+5))
        exact_checks+=1
# Independent formal derivative operator -D*d/dD applied to p(D)*exp(-D).
p=[1]
for _ in range(4):
    out=[0]*(len(p)+1)
    for j,c in enumerate(p):
        out[j]-=j*c;out[j+1]+=c
    p=out
assert p==[0,-1,7,-6,1]
exact_checks+=1
with localcontext() as ctx:
    ctx.prec=100
    a=D(1)/D(2).sqrt(); tol=D('1e-80'); max_poly=D(0);max_kernel=D(0)
    for t in [D(-1),-a,D('-.31'),D(0),D('.81'),a,D(1)]:
        for n in range(4):
            data=[(-a)**n,a**n,n*(-a)**(n-1) if n else D(0),n*a**(n-1) if n else D(0)]
            max_poly=max(max_poly,abs(sum(x*y for x,y in zip(card(t,a),data))-power(t,n)),abs(sum(x*y for x,y in zip(dcard(t,a),data))-(n*power(t,n-1) if n else 0)))
        for m in range(9):
            n=m+4;data=[(-a)**n,a**n,n*(-a)**(n-1),n*a**(n-1)]
            defect=n*power(t,n-1)-sum(x*y for x,y in zip(dcard(t,a),data))
            max_kernel=max(max_kernel,abs(kernel_moment(t,a,m)-defect/D(math.prod(range(m+1,m+5)))))
    assert max_poly<tol and max_kernel<tol
    times=list(map(D,['0','1e-10','.03','.7','2','0','45','.1']))
    currents=list(map(D,['.12','-.05','.07','0','-.13','.04','.11','-.02']))
    max_rec=D(0);max_fd=D(0);max_constant=D(0);comparisons=0
    for tau_c in map(D,['.7','13','140']):
      for t in [D(-1),-a,D(0),a,D(1)]:
        tau=tau_c*t.exp();F,F1,F2,u,u1,u2=D(1),D(0),D(0),D(0),D(0),D(0)
        for k,(dt,I) in enumerate(zip(times,currents),1):
            d=dt/tau;E=(-d).exp();E1=d*E;E2=(d*d-d)*E
            F,F1,F2,u,u1,u2=E*F,E*F1+E1*F,E*F2+2*E1*F1+E2*F,E*u+(1-E)*I,E*u1+E1*(u-I),E*u2+2*E1*u1+E2*(u-I)
            dose=sum(times[:k])/tau;ef=(-dose).exp();ref=[ef,dose*ef,(dose*dose-dose)*ef]
            ru=[D(0),D(0),D(0)]
            for j in range(k):
                b=sum(times[j+1:k])/tau;c=b+times[j]/tau;eb=(-b).exp();ec=(-c).exp()
                term=[eb-ec,b*eb-c*ec,(b*b-b)*eb-(c*c-c)*ec]
                ru=[x+currents[j]*y for x,y in zip(ru,term)]
            max_rec=max(max_rec,*[abs(x-y) for x,y in zip([F,F1,F2,u,u1,u2],ref+ru)])
            comparisons+=6
        def closed_u(x):
            tau0=tau_c*x.exp()
            return sum(currents[j]*((-sum(times[j+1:])/tau0).exp()-(-sum(times[j:])/tau0).exp()) for j in range(len(times)))
        h=D('1e-20');v0=closed_u(t);vp=closed_u(t+h);vm=closed_u(t-h)
        max_fd=max(max_fd,abs((vp-vm)/(2*h)-u1),abs((vp-2*v0+vm)/(h*h)-u2))
        fc,fc1,fc2,uc,uc1,uc2=D(1),D(0),D(0),D(0),D(0),D(0);I=D('.12')
        for dt in times:
            d=dt/tau;E=(-d).exp();E1=d*E;E2=(d*d-d)*E
            fc,fc1,fc2,uc,uc1,uc2=E*fc,E*fc1+E1*fc,E*fc2+2*E1*fc1+E2*fc,E*uc+(1-E)*I,E*uc1+E1*(uc-I),E*uc2+2*E1*uc1+E2*(uc-I)
            max_constant=max(max_constant,abs(uc-I*(1-fc)),abs(uc1+I*fc1),abs(uc2+I*fc2))
    assert max_rec<tol and max_constant<tol and max_fd<D('1e-35')
    numeric={'precision_decimal_digits':100,'chronological_recurrence_component_comparisons':comparisons,'max_recurrence_vs_suffix_error':str(max_rec),'finite_difference_step':'1e-20','max_first_second_central_finite_difference_error':str(max_fd),'max_constant_current_identity_error':str(max_constant),'optimal_anchor_polynomial_reproduction_max_error':str(max_poly),'optimal_anchor_kernel_moment_max_error':str(max_kernel)}
result={'exact_rational_checks':exact_checks,'exact_kernel_moment_scope':'five query locations, a=1/2, s powers 0..8; includes extrapolation beyond anchors','fourth_derivative_polynomial':p,'numeric':numeric,'storage':{}}
